query ReactionViewerRelayLazyQuery(
  $id: ID!
) {
  node(id: $id) {
    __typename
    ... on Comment {
      __isComment: __typename
      ...ReactionViewerRelayGroups
    }
    id
  }
}

fragment ReactionViewerRelayGroups on Reactable {
  __isReactable: __typename
  reactionGroups {
    content
    viewerHasReacted
    reactors(first: 5) {
      totalCount
      nodes {
        __typename
        ... on User {
          login
          __typename
        }
        ... on Bot {
          login
          __typename
        }
        ... on Organization {
          login
          __typename
        }
        ... on Mannequin {
          login
          __typename
        }
        ... on Node {
          __isNode: __typename
          id
        }
      }
    }
  }
}
